export const dictionaries: Record<DictionaryLanguage, Dictionary> = { uz, ru, en };

export function toNewLatin(value: string) {
  return value
    .replace(/sh/gi, (m) => m[0] === "s" ? "ş" : "Ş")
    .replace(/ch/gi, (m) => m[0] === "c" ? "ç" : "Ç")
    .replace(/o['‘’ʻʼ`]/g, "ō").replace(/O['‘’ʻʼ`]/g, "Ō")
    .replace(/g['‘’ʻʼ`]/g, "ḡ").replace(/G['‘’ʻʼ`]/g, "Ḡ");
}

export function translate(key: TranslationKey, lang: Language = "uz", vars?: Vars) {
  const base = lang === "uz_new" ? "uz" : lang;
  let text: string = dictionaries[base][key];
  if (vars) for (const [name, value] of Object.entries(vars)) text = text.replaceAll(`{${name}}`, String(value));
  return lang === "uz_new" ? toNewLatin(text) : text;
}

const PLACE_KEYS = new Set(Object.keys(uz).filter((key) => key.startsWith("place.")));
export function translatePlace(value: string, lang: Language = "uz") {
  const key = `place.${value}`;
  return PLACE_KEYS.has(key) ? translate(key as TranslationKey, lang) : value;
}
